head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
// session 값을 control 에 binding 시키는 함수.
scwin.vScrenID = 'ULDSTF26501.gfm';
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.initPage = function() {
    if (js_market == "9") {
        rdo_MKT_ID.setDisabled(false);
    } else {
        rdo_MKT_ID.setDisabled(true);
    }
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    $c.stf.setObjectValue(chk_TODAY, "Y");
    $c.stf.setObjectValue(edt_TODAY, $c.ut.cGetToday2());
    $c.stf.showObj(panel_today, true);
    // alert(gLdMktTp);
    $c.stf.setObjectValue(chk_PERIOD, "N");
    $c.stf.showObj(panel_period, false);
    $c.stf.setObjectValue(cmb_PeriodTp, "5");
};
scwin.fn_listDisclosureReceiveStatistic = function() {
    var MKT_ID = $c.stf.getObjectValue(rdo_MKT_ID);
    if (MKT_ID == "") {
        alert("[시장구분]을 선택하세요.");
        return;
    }
    var MKT_ID = $c.stf.getObjectValue(rdo_MKT_ID);
    var SDATE = $c.stf.getObjectValue(edt_SDATE);
    var EDATE = $c.stf.getObjectValue(edt_EDATE);
    var TODAY = $c.stf.getObjectValue(edt_TODAY);
    var bTODAY = $c.stf.getObjectValue(chk_TODAY);
    var bPERIOD = $c.stf.getObjectValue(chk_PERIOD);
    if (bTODAY == "N" && bPERIOD == "N") {
        alert("[금일] 또는 [기간별]을 선택하세요.");
        return;
    }
    var FLAG = "TODAY";
    FLAG = (bTODAY == "Y") ? "TODAY" : "PERIOD";
    if (FLAG == "TODAY") {
        if (TODAY == "") {
            alert("[금일-일자]를 입력하세요.");
            edt_TODAY.focus();
            return;
        }
    } else {
        if (SDATE == "") {
            alert("[기간별-시작일]을 입력하세요.");
            edt_SDATE.focus();
            return;
        }
        if (EDATE == "") {
            alert("[기간별-종료일]을 입력하세요.");
            edt_EDATE.focus();
            return;
        }
    }
    $c.cm.ShowWin(grd_TODAY);
    $c.cm.ShowWin(grd_PERIOD);
    var url = "/DisclosureCountStatistics.do?method=listDisclosureReceiveStatistic";
    url += "&MKT_ID=" + MKT_ID;
    url += "&TODAY=" + TODAY;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&FLAG=" + FLAG;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_TODAY.DataID = url;

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_TODAY.Reset();
    url = "/DisclosureCountStatistics.do?method=listDisclosureReceivePeriod";
    url += "&MKT_ID=" + MKT_ID;
    url += "&TODAY=" + TODAY;
    url += "&SDATE=" + SDATE;
    url += "&EDATE=" + EDATE;
    url += "&FLAG=" + FLAG;
    dts_PERIOD.DataID = url;

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_PERIOD.Reset();
};
scwin.fn_StatusCnt = function() {

	//----W-Craft WebSquare 변환 확인: GWinOpen----//
    $c.frame.path("../../").GWinOpen("ULDSTF35300", "/dsclsrch/ULDSTF26503.gfm", "공시건수조회", 20, 20, 1270, 780, "");
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_mkt, false);
};
scwin.btn_SEARCH_onclick = function() {
    scwin.fn_listDisclosureReceiveStatistic();
};
scwin.dts_PERIOD_OnLoadError = function() {
    $c.stf.alert_error(dts_PERIOD);
};
scwin.btn_SDATE_onclick = function() {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_SDATE);
};
scwin.btn_EDATE_onclick = function() {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE);
};
scwin.btn_GridToExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_TODAY, "요약재무정보", 'c:\\abs\\test.xls', 16);
};
scwin.chk_TODAY_onclick = function() {
    if ($c.stf.getObjectValue(chk_TODAY) == "Y") {
        $c.cm.setColumnProp(grd_PERIOD, 'SEND_D', 'Show', 'true');
        dts_PERIOD.removeAll();
        dts_TODAY.removeAll();
        $c.stf.setObjectValue(chk_PERIOD, "N");
        $c.stf.showObj(panel_period, false);
        $c.stf.showObj(panel_today, true);
    }
};
scwin.chk_PERIOD_onclick = function() {
    if ($c.stf.getObjectValue(chk_PERIOD) == "Y") {
        $c.cm.setColumnProp(grd_PERIOD, 'SEND_D', 'Show', 'false');
        dts_PERIOD.removeAll();
        dts_TODAY.removeAll();
        $c.stf.setObjectValue(chk_TODAY, "N");
        $c.stf.showObj(panel_period, true);
        $c.stf.showObj(panel_today, false);
    }
};
scwin.dts_TODAY_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_TODAY);
};
scwin.dts_TODAY_OnLoadError = function() {
    $c.stf.alert_error(dts_TODAY);
};
scwin.dts_PERIOD_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_PERIOD);
};
scwin.btn_EXCEL_PERIOD_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_PERIOD, "요약재무정보", 'c:\\abs\\test.xls', 16);
};
scwin.btn_TODAY_onclick = function() {

	//----W-Craft WebSquare 변환 확인: popUpCalendar2----//
    popUpCalendar2(edt_TODAY);
};
scwin.btn_STATUS_CNT_onclick = function() {
    scwin.fn_StatusCnt();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_HideDebugCtrls();
    scwin.initPage();
};
